from src.person import Person
from src.tad_simple_list import TADSimpleList


class TestTADLinkListSearch:
    
    def test_add_tail_tad_link_list(self, tad_link_list: TADSimpleList, test_data):
        assert tad_link_list.is_empty() == True
        for person in test_data["test_issue_ticket"]["normal"]:
            tad_link_list.add_tail(Person(
                phone=person["phone"],
                attendance_type=person["att_type"],
                bi=person["bi"],
                name=person["name"],
                ticket=person["ticket"]
            ))
            
        assert tad_link_list.is_empty() == False
    
    def test_remove_head_tad_link_list(self, tad_link_list: TADSimpleList, test_data):
        person = tad_link_list.remove_head()
        assert person.name == test_data["test_issue_ticket"]["normal"][0]["name"]
        assert person.ticket == test_data["test_issue_ticket"]["normal"][0]["ticket"]
        assert person.bi == test_data["test_issue_ticket"]["normal"][0]["bi"]
        assert person.phone == test_data["test_issue_ticket"]["normal"][0]["phone"]
        assert person.type == test_data["test_issue_ticket"]["normal"][0]["att_type"]
        
        person = tad_link_list.remove_head()
        assert person.name == test_data["test_issue_ticket"]["normal"][1]["name"]
        assert person.ticket == test_data["test_issue_ticket"]["normal"][1]["ticket"]
        assert person.bi == test_data["test_issue_ticket"]["normal"][1]["bi"]
        assert person.phone == test_data["test_issue_ticket"]["normal"][1]["phone"]
        assert person.type == test_data["test_issue_ticket"]["normal"][1]["att_type"]
        
        [tad_link_list.remove_head() for _ in range(5)]
        
        assert tad_link_list.is_empty() == False
    
    def test_find_tad_link_list(self, tad_link_list: TADSimpleList, test_data):
        node = tad_link_list.find(test_data["test_issue_ticket"]["normal"][1]["ticket"])
        assert node == None
        
        node = tad_link_list.find(test_data["test_issue_ticket"]["normal"][9]["ticket"])
        assert node != None
        assert node.person.name == test_data["test_issue_ticket"]["normal"][9]["name"]
        assert node.person.ticket == test_data["test_issue_ticket"]["normal"][9]["ticket"]
        assert node.person.bi == test_data["test_issue_ticket"]["normal"][9]["bi"]
        assert node.person.phone == test_data["test_issue_ticket"]["normal"][9]["phone"]
        assert node.person.type == test_data["test_issue_ticket"]["normal"][9]["att_type"]
        
        node = tad_link_list.find(test_data["test_issue_ticket"]["normal"][10]["ticket"])
        assert node != None
        assert node.person.name != test_data["test_issue_ticket"]["normal"][9]["name"]
        assert node.person.ticket != test_data["test_issue_ticket"]["normal"][9]["ticket"]
        assert node.person.name == test_data["test_issue_ticket"]["normal"][10]["name"]
        assert node.person.ticket == test_data["test_issue_ticket"]["normal"][10]["ticket"] 
        assert node.person.bi == test_data["test_issue_ticket"]["normal"][10]["bi"]
        assert node.person.phone == test_data["test_issue_ticket"]["normal"][10]["phone"]
        assert node.person.type == test_data["test_issue_ticket"]["normal"][10]["att_type"]
    
    def test_get_all_nodes_tad_link_list(self, tad_link_list: TADSimpleList, test_data):
        test_data = test_data["test_issue_ticket"]["normal"][7:]
        
        _list = tad_link_list.get_all_nodes()
        assert len(test_data) == len(_list)
        for person, v_person in zip(_list, test_data):
            assert person[1] == v_person["name"]
            assert person[0] == v_person["ticket"]
            assert person[2] == v_person["att_type"]
            
    def test_remove_node_tad_link_list(self, tad_link_list: TADSimpleList, test_data):
        node = tad_link_list.find(test_data["test_issue_ticket"]["normal"][11]["ticket"])
        assert node != None
        person = tad_link_list.remove_node(node)
        assert person.name == test_data["test_issue_ticket"]["normal"][11]["name"]
        assert person.ticket == test_data["test_issue_ticket"]["normal"][11]["ticket"]
        assert person.bi == test_data["test_issue_ticket"]["normal"][11]["bi"]
        assert person.phone == test_data["test_issue_ticket"]["normal"][11]["phone"]
        assert person.type == test_data["test_issue_ticket"]["normal"][11]["att_type"]
        node = tad_link_list.find(test_data["test_issue_ticket"]["normal"][11]["ticket"])
        assert node == None
        
        node = tad_link_list.find(test_data["test_issue_ticket"]["normal"][9]["ticket"])
        assert node != None
        person = tad_link_list.remove_node(node)
        assert person.name == test_data["test_issue_ticket"]["normal"][9]["name"]
        assert person.ticket == test_data["test_issue_ticket"]["normal"][9]["ticket"]
        assert person.bi == test_data["test_issue_ticket"]["normal"][9]["bi"]
        assert person.phone == test_data["test_issue_ticket"]["normal"][9]["phone"]
        assert person.type == test_data["test_issue_ticket"]["normal"][9]["att_type"]
        node = tad_link_list.find(test_data["test_issue_ticket"]["normal"][9]["ticket"])
        assert node == None
